<template><section class="page-card"><div class="page-header"><div><h1 class="page-title">菜单权限管理</h1><p class="muted">菜单、目录和按钮权限是前端导航与后端授权的共享配置。</p></div><el-button v-has-permi="'system:menu:create'" type="primary" @click="openCreate">新增菜单</el-button></div><div v-if="loading" class="loading-state"><el-icon class="is-loading"><Loading /></el-icon></div><el-table v-else :data="tree" row-key="id" border default-expand-all :tree-props="{children:'children'}"><el-table-column prop="menuName" label="名称" min-width="180"/><el-table-column prop="menuType" label="类型" width="100"><template #default="{row}"><el-tag>{{typeLabel(row.menuType)}}</el-tag></template></el-table-column><el-table-column prop="routePath" label="路由" min-width="180"/><el-table-column prop="component" label="安全组件映射" min-width="180"/><el-table-column prop="permissionCode" label="权限编码" min-width="200"/><el-table-column label="状态" width="90"><template #default="{row}"><StatusTag :status="row.status"/></template></el-table-column><el-table-column label="操作" min-width="210" fixed="right"><template #default="{row}"><div class="table-actions"><el-button v-has-permi="'system:menu:update'" text type="primary" @click="openEdit(row)">编辑</el-button><el-button v-has-permi="'system:menu:status'" text @click="toggleStatus(row)">{{row.status==='active'?'停用':'启用'}}</el-button><el-button v-has-permi="'system:menu:delete'" text type="danger" :disabled="row.isBuiltin" @click="remove(row)">删除</el-button></div></template></el-table-column></el-table><ManagementDrawer v-model="drawer.open" :title="drawer.title" :loading="saving" @save="save"><el-form class="drawer-form" label-position="top"><el-form-item label="上级菜单"><el-tree-select v-model="form.parentId" :data="parentTree" node-key="id" check-strictly clearable :props="{label:'menuName',children:'children',value:'id'}"/></el-form-item><el-form-item label="菜单名称" required><el-input v-model="form.menuName"/></el-form-item><el-form-item label="类型"><el-radio-group v-model="form.menuType"><el-radio value="directory">目录</el-radio><el-radio value="menu">菜单</el-radio><el-radio value="button">按钮</el-radio></el-radio-group></el-form-item><el-form-item label="路由地址"><el-input v-model="form.routePath" placeholder="例如 /system/example" :disabled="form.menuType==='button'"/></el-form-item><el-form-item label="组件标识"><el-input v-model="form.component" placeholder="例如 system/users/index" :disabled="form.menuType!=='menu'"/><HelpIcon content="前端只接受固定安全映射表中的组件标识。未知标识会降级为“迁移中”页，绝不会动态加载任意模块。"/></el-form-item><el-form-item label="权限编码"><el-input v-model="form.permissionCode" placeholder="例如 system:example:view"/></el-form-item><el-form-item label="排序"><el-input-number v-model="form.sortOrder" :min="0"/></el-form-item><el-form-item label="状态"><el-radio-group v-model="form.status"><el-radio value="active">启用</el-radio><el-radio value="inactive">停用</el-radio></el-radio-group></el-form-item></el-form></ManagementDrawer></section></template>
<script setup>import { computed,onMounted,reactive,ref } from 'vue';import { ElMessage,ElMessageBox } from 'element-plus';import { request } from '@/api/http';import ManagementDrawer from '@/components/ManagementDrawer.vue';import StatusTag from '@/components/StatusTag.vue';import HelpIcon from '@/components/HelpIcon.vue';const tree=ref([]),rows=ref([]),loading=ref(false),saving=ref(false);const drawer=reactive({open:false,title:'',mode:'create',id:null});const form=reactive({parentId:null,menuName:'',menuType:'menu',routePath:'',component:'',permissionCode:'',icon:'Menu',sortOrder:0,status:'active'});const parentTree=computed(()=>tree.value);const typeLabel=value=>({directory:'目录',menu:'菜单',button:'按钮'}[value]||value);async function load(){loading.value=true;try{const data=(await request({url:'/system/menus'})).data||{};rows.value=data.rows||[];tree.value=data.tree||[]}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}function resetForm(){Object.assign(form,{parentId:null,menuName:'',menuType:'menu',routePath:'',component:'',permissionCode:'',icon:'Menu',sortOrder:0,status:'active'})}function openCreate(){resetForm();Object.assign(drawer,{open:true,title:'新增菜单',mode:'create',id:null})}function openEdit(row){resetForm();Object.assign(form,{parentId:row.parentId,menuName:row.menuName,menuType:row.menuType,routePath:row.routePath||'',component:row.component||'',permissionCode:row.permissionCode||'',icon:row.icon||'Menu',sortOrder:row.sortOrder,status:row.status});Object.assign(drawer,{open:true,title:'编辑菜单',mode:'edit',id:row.id})}async function save(){if(!form.menuName)return ElMessage.warning('请填写菜单名称。');saving.value=true;try{if(drawer.mode==='create')await request({method:'post',url:'/system/menus',data:form});else await request({method:'put',url:`/system/menus/${drawer.id}`,data:form});ElMessage.success('保存成功。');drawer.open=false;load()}catch(e){ElMessage.error(e.message)}finally{saving.value=false}}async function toggleStatus(row){try{await ElMessageBox.confirm(`确定${row.status==='active'?'停用':'启用'}“${row.menuName}”吗？`,'状态确认',{type:'warning'});await request({method:'patch',url:`/system/menus/${row.id}/status`,data:{status:row.status==='active'?'inactive':'active'}});ElMessage.success('状态已更新。');load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message)}}async function remove(row){try{await ElMessageBox.confirm('只有无子菜单、无角色授权的非内置菜单可删除；通常建议停用。是否继续？','删除菜单',{type:'warning'});await request({method:'delete',url:`/system/menus/${row.id}`});ElMessage.success('菜单已删除。');load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message)}}onMounted(load);</script>
